css:
.sign-in {
  max-inline-size: 24rem;
  margin-inline: auto;
  padding-block: var(--va-space-8, 2rem);
  padding-inline: var(--va-space-4, 1rem);
}

.sign-in h1 {
  margin-block: 0 var(--va-space-6, 1.5rem);
}

.sign-in__form {
  display: flex;
  flex-direction: column;
  gap: var(--va-space-4, 1rem);
}

.sign-in__form va-button {
  align-self: flex-start;
}

js:
// Clear the server-side "Incorrect password" error once the user edits the password.
const password = document.getElementById('password');

password?.addEventListener('input', () => {
  if (password.hasAttribute('error')) password.removeAttribute('error');
});
